SELECT column1, column2 FROM table;
SELECT * FROM table;
SELECT DISTINCT column FROM table;

SELECT * FROM table WHERE age > 30;
SELECT * FROM table WHERE age > 30 AND city = 'NY';
SELECT * FROM table WHERE country IN ('US', 'UK');
SELECT * FROM table WHERE age BETWEEN 20 AND 30;
SELECT * FROM table WHERE name LIKE 'A%';

SELECT COUNT(*) FROM table;
SELECT SUM(salary) FROM employees;
SELECT AVG(price) FROM products;
SELECT MIN(age), MAX(age) FROM users;
SELECT department, AVG(salary) FROM employees GROUP BY department;
SELECT department, AVG(salary) FROM employees GROUP BY department HAVING AVG(salary) > 50000;

CREATE TABLE employees (id INT PRIMARY KEY, name VARCHAR(100), salary DECIMAL(10,2));
ALTER TABLE employees ADD COLUMN department VARCHAR(50);
DROP TABLE employees;

INSERT INTO employees (id, name, salary) VALUES (1, 'John', 50000);
UPDATE employees SET salary = 60000 WHERE id = 1;
DELETE FROM employees WHERE id = 1;
